 4→
 5→test("parseLine splits the code from its fields", () => {
 6→  assert.deepEqual(parseLine("x1,3,4"), { code: "x1", fields: ["3", "4"] });
 7→});
 8→
 9→test("combine treats a non-number as zero", () => {
10→  assert.equal(combine([3, NaN, 4]), 7);
11→});
12→
13→test("tally adds a code's counts across lines", () => {
14→  assert.deepEqual(tally(["x,3", "y,2", "x,4"]), { x: 7, y: 2 });
15→});

